"""Offline HTML comparison report. All data, chart code and styles are embedded."""
from __future__ import annotations

import json


def generate_report(path, metadata, results):
    payload = json.dumps(dict(metadata=metadata, results=results), allow_nan=False).replace('<', '\\u003c')
    path.write_text(TEMPLATE.replace('__COMPARISON_DATA__', payload), encoding='utf-8')


TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Naartjie tracker comparison</title>
<style>
:root{font:15px/1.5 system-ui,sans-serif;color:#17291f;background:#f4f7f4;--green:#176c43;--muted:#617168}
*{box-sizing:border-box}body{margin:0}main{max-width:1440px;margin:auto;padding:32px}h1{font-size:32px;line-height:1.2;margin:0 0 12px}h2{font-size:21px;margin:0 0 16px}h3{font-size:17px;margin:0 0 8px}p{margin:8px 0}small,.muted{color:var(--muted)}.eyebrow{letter-spacing:.12em;text-transform:uppercase;font-size:12px;color:var(--green);font-weight:700}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.card,.panel{background:white;border:1px solid #dce5de;border-radius:10px;padding:20px}.card strong{display:block;font-size:18px;overflow-wrap:anywhere}.card span{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.panel{margin:18px 0}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button,select,input{font:inherit;border:1px solid #b8cabe;background:white;border-radius:6px;padding:8px 12px;color:inherit}button{cursor:pointer}button.selected{background:var(--green);color:white;border-color:var(--green)}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #87bfa0}a{color:var(--green)}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}th,td{padding:11px 12px;text-align:right;border-bottom:1px solid #e4ebe6}th:first-child,td:first-child{text-align:left}th{background:#f2f6f3}th button{border:0;background:transparent;padding:0;font-weight:650}.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.chart{min-width:0}.chart svg{display:block;width:100%;height:auto}.legend{font-size:12px;color:var(--muted)}.method{font-size:14px}.method li{margin:6px 0}.metadata{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,monospace;max-height:500px;overflow:auto}.note{border-left:4px solid #c39328;padding:10px 14px;background:#fff9e9}.downloads{display:flex;gap:20px;flex-wrap:wrap;margin:15px 0}.table-count{margin:12px 0;color:var(--muted)}@media(max-width:760px){main{padding:18px}.cards,.charts{grid-template-columns:1fr}h1{font-size:26px}.card{padding:14px}}
</style></head><body><main>
<div class="eyebrow">Citrusvision · Separate experiment</div><h1>Naartjie tracker comparison</h1>
<p>Compare processing speed and raw-ID stability on one shared video and detector. Review the individual measures to choose a tracker deliberately.</p>
<div id="cards" class="cards"></div>
<div class="note">Raw tracker IDs are retained without merging. Lifetime, consistency and suspected fragmentation describe observed output; physical fruit identity has no manual ground-truth labels. No tracker is selected automatically.</div>
<section class="panel"><h2>Comparison</h2><div id="modes" class="controls" role="group" aria-label="Timing mode"></div>
<p id="scope" class="muted"></p><div class="downloads"><a href="comparison_summary.csv" download>Comparison CSV</a><a href="comparison_summary.json" download>Comparison JSON</a><a href="run_metadata.json" download>Run metadata</a></div>
<div class="scroll"><table id="summary" aria-label="Tracker comparison"></table></div>
<p class="muted">Active IDs are the raw IDs returned in each frame, including empty frames in the average. “Substantial” uses the application-defined observed interval and consistency thresholds below; it does not measure a fruit’s true visible lifetime.</p></section>
<div class="charts" id="charts"></div>
<section class="panel"><h2>Per-ID observations</h2><div class="controls"><label>Tracker <select id="track-select"></select></label><label>Raw ID <input id="search" placeholder="Filter raw ID" type="search"></label><a id="tracks-download" download>Tracks CSV</a><a id="events-download" download>Events CSV</a><a id="observations-download" download>Raw observations CSV</a></div>
<p class="table-count" id="track-count"></p><div class="scroll"><table id="tracks" aria-label="Per-ID results"></table></div></section>
<section class="panel method"><h2>Measurement definitions</h2><ul>
<li>Processing FPS = complete processed frame count ÷ summed measured processing seconds. Mean time/frame = 1,000 × measured seconds ÷ processed frame count. Source video FPS is displayed separately.</li>
<li>Full mode measures detector preprocessing, inference, postprocessing/NMS, CPU box transfer and tracker update. Cached mode measures the box adapter and tracker update, including configured camera-motion compensation. Cached replay FPS excludes detection and cannot establish complete conveyor throughput.</li>
<li>CUDA is synchronized before and after each timed section. Model loading, video decoding, cache I/O, input verification, metrics, overlays, encoding and report writing are excluded. Warm-up uses disposable state and is excluded; every measured tracker starts fresh at frame zero and processes the complete video.</li>
<li>Lifetime = last source timestamp − first source timestamp. A one-frame ID has zero elapsed lifetime. Frame percentage = observed frames ÷ all processed video frames. Consistency = observed frames ÷ (last frame − first frame + 1). First/last observations may be clipped by the video boundaries.</li>
<li>Suspected ID Fragmentations pair a newly observed ID with a recently missing ID of the same class and comparable box size, near its timestamp-based linear continuation. Candidate pairs are matched by nearest normalized distance, once per old/new ID in that frame. Nearby fruit, exits and new entries can produce false candidates. IDs remain separate.</li>
<li>All tracker algorithm settings come from the installed YAMLs. Only the common runtime device is added. Production-specific edge-box association and corrected fruit IDs are excluded. Default ReID is off in the inspected installation; this does not compare appearance-enabled variants. TrackTrack receives common post-NMS boxes, without YOLO-specific recovered pre-NMS candidates, matching the D-FINE raw-box interface.</li>
<li>Processing speed depends on hardware load and tracker order. One pass per tracker supports an engineering comparison, not a controlled repeated statistical benchmark. Check recorded hardware/load metadata and repeat on an idle system before a final choice.</li>
</ul><p id="diagnostics"></p><p id="detector-reference"></p><p id="warmup"></p>
<p>Methodology reference: <a href="https://docs.ultralytics.com/modes/track/">official Ultralytics tracking documentation</a> and its linked <a href="https://www.youtube.com/watch?v=ZsxHIN2PoiY">YOLO26 speed, FPS and ID-stability comparison</a>. Diagnostic thresholds and fragmentation rules are application-defined extensions. This report’s charts work offline.</p>
<details><summary>Reproducibility metadata and installed tracker configurations</summary><pre class="metadata" id="metadata"></pre></details></section>
</main><script id="comparison-data" type="application/json">__COMPARISON_DATA__</script><script>
'use strict';
const DATA=JSON.parse(document.getElementById('comparison-data').textContent),meta=DATA.metadata;
const modes=[...new Set(DATA.results.map(r=>r.summary.mode))];let mode=modes.includes('full')?'full':modes[0],sortKey=null,sortDirection=1;
const $=id=>document.getElementById(id), el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
const fmt=(v,d=2)=>v===null||v===undefined?'—':typeof v==='number'?v.toLocaleString('en',{maximumFractionDigits:d}):v;
const cardItems=[['Video',meta.video.filename],['Detector',meta.detector_checkpoint.split(/[\\/]/).pop()],['Processed frames',fmt(meta.video.frame_count,0)],['Source video FPS',fmt(meta.video.source_fps)],['Resolution',`${meta.video.width} × ${meta.video.height}`],['Processing hardware',`${meta.hardware} (${meta.selected_device})`]];
cardItems.forEach(([label,value])=>{const c=el('div');c.className='card';c.append(el('span',label),el('strong',value));$('cards').append(c)});
const columns=[['Tracker','tracker_name'],['Processing FPS','processing_fps'],['Mean ms/frame','average_time_ms'],['Total seconds','total_processing_seconds'],['Unique raw IDs','unique_raw_ids'],['Mean lifetime (s)','mean_lifetime_seconds'],['Median lifetime (s)','median_lifetime_seconds'],['Mean consistency (%)','mean_consistency_percent'],['Suspected ID Fragmentations','suspected_id_fragmentations'],['Max active IDs','maximum_active_ids'],['Mean active IDs','mean_active_ids'],['Final active IDs','final_active_ids'],['Substantial IDs','substantial_persistence_ids'],['Substantial IDs (%)','substantial_persistence_percent'],['Min lifetime (s)','minimum_lifetime_seconds'],['Max lifetime (s)','maximum_lifetime_seconds'],['Median consistency (%)','median_consistency_percent'],...meta.diagnostic_settings.short_lifetime_seconds.flatMap(t=>[[`IDs < ${t} s`,`short_lived_under_${t}s_count`],[`IDs < ${t} s (%)`,`short_lived_under_${t}s_percent`]])];
function renderSummary(results){const table=$('summary');table.replaceChildren();const head=el('thead'),tr=el('tr');columns.forEach(([name,key])=>{const th=el('th'),b=el('button',name);b.setAttribute('aria-label',`Sort by ${name}`);b.onclick=()=>{sortDirection=sortKey===key?-sortDirection:1;sortKey=key;render()};th.append(b);tr.append(th)});head.append(tr);table.append(head);const body=el('tbody');let rows=results.map(r=>r.summary);if(sortKey)rows.sort((a,b)=>{const x=a[sortKey],y=b[sortKey];if(x===null)return 1;if(y===null)return -1;return sortDirection*(typeof x==='string'?x.localeCompare(y):x-y)});rows.forEach(row=>{const tr=el('tr');columns.forEach(([,key])=>tr.append(el('td',fmt(row[key]))));body.append(tr)});table.append(body)}
const svgNS='http://www.w3.org/2000/svg';function svgEl(tag,attrs,text){const n=document.createElementNS(svgNS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text!==undefined)n.textContent=text;return n}
function chart(title,labels,series,unit){const panel=el('section');panel.className='panel chart';panel.append(el('h3',title));const width=640,height=labels.length*45+60,max=Math.max(1,...series.flatMap(s=>s.values.filter(v=>v!==null))),svg=svgEl('svg',{viewBox:`0 0 ${width} ${height}`,role:'img','aria-label':title});labels.forEach((label,i)=>{const y=32+i*45;svg.append(svgEl('text',{x:4,y:y+10,fill:'#42564a','font-size':13},label));series.forEach((s,j)=>{const value=s.values[i];if(value===null)return;const yy=y+j*(24/series.length);const bar=svgEl('rect',{x:125,y:yy,width:390*value/max,height:Math.max(8,22/series.length-2),rx:2,fill:s.color});bar.append(svgEl('title',{},`${label}: ${s.name} ${fmt(value)} ${unit}`));svg.append(bar,svgEl('text',{x:130+390*value/max,y:yy+10,fill:'#283c30','font-size':11},fmt(value)))});});panel.append(svg);const legend=el('p',series.map(s=>s.name).join(' / ')+(unit?' · '+unit:''));legend.className='legend';panel.append(legend);$('charts').append(panel)}
function renderCharts(results){$('charts').replaceChildren();const labels=results.map(r=>r.summary.tracker_name),one=(title,key,unit)=>chart(title,labels,[{name:title,color:'#27815a',values:results.map(r=>r.summary[key])}],unit);
one(mode==='full'?'Detection + tracking processing FPS':'Tracker-only processing FPS','processing_fps','frames/s');one('Mean processing time per frame','average_time_ms','ms');chart('Track lifetime',labels,[{name:'Mean',color:'#27815a',values:results.map(r=>r.summary.mean_lifetime_seconds)},{name:'Median',color:'#c4932f',values:results.map(r=>r.summary.median_lifetime_seconds)}],'s');one('Unique raw IDs','unique_raw_ids','IDs');one('Mean track consistency','mean_consistency_percent','%');one('Suspected ID Fragmentations','suspected_id_fragmentations','candidates');
const selected=results.find(r=>r.summary.tracker_key===$('track-select').value)||results[0];chart(`${selected.summary.tracker_name}: lifetime distribution`,selected.summary.lifetime_distribution.map(x=>x.label),[{name:'Observed raw IDs',color:'#27815a',values:selected.summary.lifetime_distribution.map(x=>x.count)}],'IDs');}
function renderTracks(results){const selected=results.find(r=>r.summary.tracker_key===$('track-select').value)||results[0],summary=selected.summary;const both=modes.length>1,folder=summary.tracker_key+(both?'/'+mode:'');['tracks','events','observations'].forEach(kind=>$(kind+'-download').href=folder+'/'+kind+'.csv');let rows=selected.tracks.filter(t=>String(t.track_id).includes($('search').value));$('track-count').textContent=`${rows.length} of ${selected.tracks.length} raw IDs · showing up to 200; the CSV contains every ID.`;rows=rows.slice(0,200);const cols=[['Raw ID','track_id'],['First frame','first_frame'],['Last frame','last_frame'],['First time (s)','first_timestamp'],['Last time (s)','last_timestamp'],['Observed frames','observed_frames'],['Possible frames','possible_frames_between_first_and_last'],['Lifetime (s)','lifetime_seconds'],['Video frames (%)','processed_video_frames_percent'],['Consistency (%)','consistency_percent'],['Mean width (px)','mean_box_width'],['Mean height (px)','mean_box_height']];const table=$('tracks');table.replaceChildren();const head=el('thead'),tr=el('tr');cols.forEach(([label])=>tr.append(el('th',label)));head.append(tr);table.append(head);const body=el('tbody');rows.forEach(row=>{const tr=el('tr');cols.forEach(([,key])=>tr.append(el('td',fmt(row[key]))));body.append(tr)});table.append(body)}
function render(){const results=DATA.results.filter(r=>r.summary.mode===mode);$('modes').replaceChildren();modes.forEach(m=>{const b=el('button',m==='full'?'Detection + tracking':'Cached tracker-only replay');b.className=m===mode?'selected':'';b.setAttribute('aria-pressed',m===mode);b.onclick=()=>{mode=m;render()};$('modes').append(b)});$('scope').textContent=mode==='full'?'Measured detection + tracking. Every tracker processes the same complete video, with identical detector settings.':'Measured tracker-only replay. Every tracker receives the identical cached detections; detector time is excluded.';const old=$('track-select').value;$('track-select').replaceChildren();results.forEach(r=>{const option=el('option',r.summary.tracker_name);option.value=r.summary.tracker_key;$('track-select').append(option)});if(results.some(r=>r.summary.tracker_key===old))$('track-select').value=old;renderSummary(results);renderTracks(results);renderCharts(results)}
$('track-select').onchange=()=>{const results=DATA.results.filter(r=>r.summary.mode===mode);renderTracks(results);renderCharts(results)};$('search').oninput=()=>renderTracks(DATA.results.filter(r=>r.summary.mode===mode));
const d=meta.diagnostic_settings;$('diagnostics').textContent=`Application-defined diagnostics: short-lived ID thresholds ${d.short_lifetime_seconds.join(', ')} s (strictly fewer); substantial persistence ≥${d.substantial_lifetime_seconds} s with ≥${d.substantial_consistency_percent}% consistency; fragmentation window ≤${d.fragmentation_window_seconds} s, distance ≤${d.fragmentation_distance_box_diagonals} box diagonals, width and height ratios 0.5–2.`;
const ref=meta.common_detection_pass;$('detector-reference').textContent=ref?`Shared detector pass: ${fmt(ref.average_time_ms)} ms/frame, ${fmt(ref.processing_fps)} detector-only FPS. These measurements are saved separately and are not added to cached replay speed.`:'';
$('warmup').textContent=`Excluded detector warm-up: ${meta.detector_warmup_frames_excluded} frames. Per-run disposable tracker warm-up: ${[...new Set(DATA.results.map(r=>r.summary.warmup_frames_excluded))].join(', ')} frames. Measured frames per tracker: ${meta.video.frame_count}. Confidence ${meta.confidence}; NMS IoU ${meta.nms_iou}; detector input ${meta.image_size.join(' × ')}. Ultralytics ${meta.ultralytics_version}. Started ${meta.date_time_utc} (UTC).`;
$('metadata').textContent=JSON.stringify(meta,null,2);render();
</script></body></html>'''
